     7	import React from 'react';
     8	import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
     9	import { ZimmTokensGlobal } from '../../theme/zimmTokensGlobal';
    10	import { ZimmFontFace } from '../../theme/fontFace';
    11	
    12	// Removes focus for non-keyboard interactions for the whole application
    13	import 'focus-visible/dist/focus-visible';
    14	
    15	import theme from '../../theme';
    16	import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
    17	import {
    18	  resolveSiteFromUrl,
    19	  getParamsFromPath,
    20	  getSites,
    21	  getLocaleByReference,
    22	} from '@salesforce/retail-react-app/app/utils/site-utils';
    23	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
    24	import { getEnvBasePath, slasPrivateProxyPath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
    25	import { createUrlTemplate } from '@salesforce/retail-react-app/app/utils/url';
    26	import createLogger from '@salesforce/pwa-kit-runtime/utils/logger-factory';
    27	import { getPasswordlessCallbackUrl } from '@salesforce/retail-react-app/app/utils/auth-utils';
    28	
    29	import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
    30	import { withReactQuery } from '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query';
    31	import { useCorrelationId } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
    32	import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
    33	import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
    34	import { generateSfdcUserAgent } from '@salesforce/retail-react-app/app/utils/sfdc-user-agent-utils';
    35	import {
    36	  DEFAULT_DNT_STATE,
    37	  STORE_LOCATOR_RADIUS,
    38	  STORE_LOCATOR_RADIUS_UNIT,
    39	  STORE_LOCATOR_DEFAULT_COUNTRY,
    40	  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
    41	  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
    42	  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
    43	  STORE_LOCATOR_SUPPORTED_COUNTRIES,
    44	} from '@salesforce/retail-react-app/app/constants';
    45	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
    46	
    47	const sfdcUserAgent = generateSfdcUserAgent();
    48	
    49	type SiteLocale = {
    50	  id: string;
    51	  alias?: string;
    52	  preferredCurrency: string;
    53	};
    54	
    55	// sfccSiteId overrides the SFCC Commerce API siteId for PWA sites whose ID differs from the
    56	// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
    57	type SiteConfig = {
    58	  id: string;
    59	  sfccSiteId?: string;
    60	  alias?: string;
    61	  l10n: {
    62	    defaultLocale: string;
    63	    supportedLocales: SiteLocale[];
    64	  };
    65	};
    66	
    67	type AppLocals = {
    68	  appConfig?: {
    69	    commerceAPI: {
    70	      proxyPath: string;
    71	      parameters: {
    72	        shortCode: string;
    73	        clientId: string;
    74	        organizationId: string;
    75	        siteId?: string;
    76	      };
    77	    };
    78	    login?: {
    79	      passwordless?: {
    80	        callbackURI?: string;
    81	      };
    82	    };
    83	    einsteinAPI?: unknown;
    84	  };
    85	  site?: Pick<SiteConfig, 'id' | 'sfccSiteId' | 'alias'>;
    86	  locale?: Pick<SiteLocale, 'id' | 'preferredCurrency'>;
    87	  buildUrl?: ReturnType<typeof createUrlTemplate>;
    88	  originalUrl?: string;
    89	};
    90	
    91	type AppConfigProps = {
    92	  children: React.ReactNode;
    93	  locals?: AppLocals;
    94	};
    95	
    96	/**
    97	 * Use the AppConfig component to inject extra arguments into the getProps
    98	 * methods for all Route Components in the app – typically you'd want to do this
    99	 * to inject a connector instance that can be used in all Pages.
   100	 *
   101	 * You can also use the AppConfig to configure a state-management library such
   102	 * as Redux, or Mobx, if you like.
   103	 */
   104	const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
   105	  const { correlationId } = useCorrelationId();
   106	  const headers = {
   107	    'correlation-id': correlationId,
   108	    sfdc_user_agent: sfdcUserAgent,
   109	  };
   110	
   111	  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
   112	  const commerceApiConfig = locals.appConfig.commerceAPI;
   113	  const locale = locals.locale?.id ?? 'en-US';
   114	
   115	  const appOrigin = getAppOrigin();
   116	  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);
   117	
   118	  const storeLocatorConfig = {
   119	    radius: STORE_LOCATOR_RADIUS,
   120	    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
   121	    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
   122	    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
   123	    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
   124	    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
   125	    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
   126	  };
   127	
   128	  // Set absolute uris for CommerceApiProvider proxies and callbacks
   129	  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
   130	  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
   131	  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;
   132	
   133	  return (
   134	    <CommerceApiProvider
   135	      shortCode={commerceApiConfig.parameters.shortCode}
   136	      clientId={commerceApiConfig.parameters.clientId}
   137	      organizationId={commerceApiConfig.parameters.organizationId}
   138	      siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
   139	      locale={locale}
   140	      currency={locals.locale?.preferredCurrency ?? ''}
   141	      redirectURI={redirectURI}
   142	      proxy={proxy}
   143	      headers={headers}
   144	      defaultDnt={DEFAULT_DNT_STATE}
   145	      logger={createLogger({ packageName: 'commerce-sdk-react' })}
   146	      passwordlessLoginCallbackURI={passwordlessCallbackURI}
   147	      // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
   148	      // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
   149	      enablePWAKitPrivateClient={true}
   150	      privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
   151	      // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
   152	      // hybridAuthEnabled={true}
   153	    >
   154	      <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
   155	        <StoreLocatorProvider config={storeLocatorConfig}>
   156	          <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
   157	            <ChakraProvider theme={theme}>
   158	              <ZimmFontFace />
   159	              <ZimmTokensGlobal />
   160	              {children}
   161	            </ChakraProvider>
   162	          </ContentfulLivePreviewProvider>
   163	        </StoreLocatorProvider>
   164	      </MultiSiteProvider>
   165	      <ReactQueryDevtools />
   166	    </CommerceApiProvider>
   167	  );
   168	};
   169	
   170	AppConfig.restore = (locals: AppLocals = {}): void => {
   171	  const path =
   172	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
   173	
   174	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
   175	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
   176	  // by matching the locale alias from the URL against each site's supportedLocales.
   177	  const defaultResolved = resolveSiteFromUrl(path);
   178	  const { localeRef } = getParamsFromPath(path);
   179	  type SupportedLocale = { id: string; alias?: string };
   180	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
   181	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
   182	  type Site = {
   183	    id: string;
   184	    sfccSiteId?: string;
   185	    alias?: string;
   186	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
   187	  };
   188	  const site: Site = localeRef
   189	    ? (getSites() as Site[]).find((s) =>
   190	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
   191	      ) ?? defaultResolved
   192	    : defaultResolved;
   193	
   194	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
   195	  // site too. Resolve the locale directly from the site we already found above.
   196	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
   197	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
   198	
   199	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
   200	  const apiConfig = {
   201	    ...appConfig.commerceAPI,
   202	    einsteinConfig: appConfig.einsteinAPI,
   203	  };
   204	
   205	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
   206	
   207	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
   208	  locals.site = site;
   209	  locals.locale = locale;
   210	  locals.appConfig = appConfig;
   211	};
   212	
   213	AppConfig.freeze = (): undefined => undefined;
   214	
   215	AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
   216	  return {
   217	    buildUrl: locals.buildUrl,
   218	    site: locals.site,
   219	    locale: locals.locale,
   220	  };
   221	};
   222	
   223	const isServerSide = typeof window === 'undefined';
   224	
   225	// Recommended settings for PWA-Kit usages.
   226	// NOTE: they will be applied on both server and client side.
   227	// retry is always disabled on server side regardless of the value from the options
   228	const options = {
   229	  queryClientConfig: {
   230	    defaultOptions: {
   231	      queries: {
   232	        retry: false,
   233	        refetchOnWindowFocus: false,
   234	        staleTime: 10 * 1000,
   235	        ...(isServerSide ? { retryOnMount: false } : {}),
   236	      },
   237	      mutations: {
   238	        retry: false,
   239	      },
   240	    },
   241	  },
   242	};
   243	
   244	export default withReactQuery(AppConfig, options);
