     1	// NOT connected to any Contentful sync script.
     2	// This file lives inside the component folder deliberately — it is a
     3	// design placeholder for the footer content type schema, prepared ahead
     4	// of the Contentful story. It will be moved to scripts/contentful/content-types/
     5	// and wired into the sync script only when that story is scheduled.
     6	
     7	// Three content types compose the footer:
     8	//   footerNavLink  — atom    — a single labelled hyperlink
     9	//   footerNavGroup — molecule — a labelled column of footerNavLink references
    10	//   footerConfig   — organism — the root footer entry (one per locale)
    11	
    12	type ContentfulFieldDef = {
    13	  id: string;
    14	  name: string;
    15	  type: string;
    16	  required: boolean;
    17	  items?: {
    18	    type: string;
    19	    linkType: string;
    20	    validations: Array<{ linkContentType: string[] }>;
    21	  };
    22	};
    23	
    24	type ContentfulContentTypeDef = {
    25	  id: string;
    26	  name: string;
    27	  displayField: string;
    28	  description: string;
    29	  fields: ContentfulFieldDef[];
    30	};
    31	
    32	const footerNavLink: ContentfulContentTypeDef = {
    33	  id: 'footerNavLink',
    34	  name: 'Footer Nav Link',
    35	  displayField: 'label',
    36	  description: 'A single navigation link rendered inside a footer column.',
    37	  fields: [
    38	    { id: 'label', name: 'Label', type: 'Symbol', required: true },
    39	    { id: 'href', name: 'URL', type: 'Symbol', required: true },
    40	  ],
    41	};
    42	
    43	const footerNavGroup: ContentfulContentTypeDef = {
    44	  id: 'footerNavGroup',
    45	  name: 'Footer Nav Group',
    46	  displayField: 'heading',
    47	  description: 'A labelled column of footer nav links (About, Contact, Help, etc.).',
    48	  fields: [
    49	    { id: 'heading', name: 'Heading', type: 'Symbol', required: true },
    50	    // Which column carries the contact icons. A flag, not a heading match — heading is
    51	    // localised, so matching its text breaks per storefront.
    52	    { id: 'showContactChannels', name: 'Show Contact Channels', type: 'Boolean', required: false },
    53	    {
    54	      id: 'links',
    55	      name: 'Links',
    56	      type: 'Array',
    57	      required: true,
    58	      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['footerNavLink'] }] },
    59	    },
    60	  ],
    61	};
    62	
    63	const footerConfig: ContentfulContentTypeDef = {
    64	  id: 'footerConfig',
    65	  name: 'Footer Config',
    66	  displayField: 'internalTitle',
    67	  description: 'Root footer entry — one per locale.',
    68	  fields: [
    69	    { id: 'internalTitle', name: 'Internal Title', type: 'Symbol', required: true },
    70	    { id: 'subscribeHeading', name: 'Subscribe Heading', type: 'Symbol', required: false },
    71	    { id: 'subscribeBody', name: 'Subscribe Body', type: 'Symbol', required: false },
    72	    {
    73	      id: 'navGroups',
    74	      name: 'Nav Groups',
    75	      type: 'Array',
    76	      required: true,
    77	      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['footerNavGroup'] }] },
    78	    },
    79	    {
    80	      id: 'legalLinks',
    81	      name: 'Legal Links',
    82	      type: 'Array',
    83	      required: false,
