     1	import { useRef, useState } from 'react';
     2	import type React from 'react';
     3	
     4	type UseZimmTextInputStateParams = {
     5	  onChange?: (value: string) => void;
     6	  /** Controlled value. When provided the caller owns the value and internal state is unused. */
     7	  value?: string;
     8	  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
     9	  defaultValue?: string;
    10	};
    11	
    12	type UseZimmTextInputStateReturn = {
    13	  value: string;
    14	  focused: boolean;
    15	  /** Label is floated when the field is focused or has a value. */
    16	  floated: boolean;
    17	  inputRef: React.RefObject<HTMLInputElement>;
    18	  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    19	  handleClear: () => void;
    20	  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
    21	};
    22	
    23	/**
    24	 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
    25	 * focus, and the derived floated-label flag. Visual tokens are NOT derived here — the border
    26	 * and label colour cascades live in `theme/components/zimmTextInput.ts`, which receives
    27	 * `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that recipe, so it
    28	 * costs no React state.
    29	 *
    30	 * Supports both modes, following the React convention: pass `value` to control it from a
    31	 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
    32	 * seeded from `defaultValue`. `onChange` fires in both modes.
    33	 * @returns value, focus and floated flags, the input ref, and the event handlers
    34	 */
    35	export const useZimmTextInputState = ({
    36	  onChange,
    37	  value: controlledValue,
    38	  defaultValue,
    39	}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
    40	  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
    41	  // `defaultValue`. Reading `value` through this indirection keeps `floated` correct in
    42	  // both modes.
    43	  const isControlled = controlledValue !== undefined;
    44	  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
    45	  const value = isControlled ? controlledValue : internalValue;
    46	  const [focused, setFocused] = useState(false);
    47	  const inputRef = useRef<HTMLInputElement>(null);
    48	
    49	  const floated = focused || value.length > 0;
    50	
    51	  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    52	    if (!isControlled) setInternalValue(e.target.value);
    53	    onChange?.(e.target.value);
    54	  };
    55	
    56	  const handleClear = () => {
    57	    if (!isControlled) setInternalValue('');
    58	    onChange?.('');
    59	    inputRef.current?.focus();
    60	  };
    61	
    62	  return { value, focused, floated, inputRef, handleChange, handleClear, setFocused };
    63	};

