    "paths": {
      "~/*": ["./*"],
      "app/*": ["./overrides/app/*"]
    },
    "isolatedModules": true,

    // Language
    "target": "ES2019",
    "lib": ["ES2019", "DOM"],
    "jsx": "react-jsx",

    // Modules
    "module": "ESNext",
